{
  "name": "MPB VFL 激光器",
  "name_en": "MPB VFL laser",
  "manufacturer": "MPB Communications",
  "description": "由 MPB Communications 提供的串口控制激光器，可开关激光输出，在恒流或恒功率模式下设置激光二极管电流与输出功率，并读取发射功率、激光二极管和 TEC 状态；还支持 SHG（二次谐波）温度设定与调谐，适用于实验中的激光输出控制和运行状态监测。",
  "description_en": "A serial-controlled laser from MPB Communications. It can enable or disable laser emission, operate in current-control or power-control mode, set laser diode current and output power, and read emission power plus laser diode and TEC status. It also supports SHG temperature setpoint control and SHG tuning for laboratory laser output control and health monitoring.",
  "actions": [
    {
      "action_name": "auto-tune_shg_async",
      "description": "异步启动 SHG 自动调谐",
      "description_en": "start SHG auto-tuning asynchronously"
    },
    {
      "action_name": "auto-tune_shg_stop_async",
      "description": "异步停止 SHG 自动调谐",
      "description_en": "stop SHG auto-tuning asynchronously"
    },
    {
      "action_name": "auto-idn",
      "description": "获取设备标识",
      "description_en": "get device identification"
    },
    {
      "action_name": "auto-status",
      "description": "获取当前设备状态",
      "description_en": "get current device status"
    },
    {
      "action_name": "auto-enabled",
      "description": "获取/设置激光输出使能状态",
      "description_en": "get/set laser emission enable state"
    },
    {
      "action_name": "auto-ctl_mode",
      "description": "获取/设置激光控制模式",
      "description_en": "get/set laser control mode"
    },
    {
      "action_name": "auto-current_sp",
      "description": "获取/设置激光二极管电流设定值",
      "description_en": "get/set laser diode current setpoint"
    },
    {
      "action_name": "auto-power_sp",
      "description": "获取/设置输出功率设定值",
      "description_en": "get/set output power setpoint"
    },
    {
      "action_name": "auto-power",
      "description": "获取激光输出功率",
      "description_en": "get laser emission power"
    },
    {
      "action_name": "auto-ld_current",
      "description": "获取激光二极管电流",
      "description_en": "get laser diode current"
    },
    {
      "action_name": "auto-ld_temp",
      "description": "获取激光二极管温度",
      "description_en": "get laser diode temperature"
    },
    {
      "action_name": "auto-tec_current",
      "description": "获取 TEC 电流",
      "description_en": "get TEC current"
    },
    {
      "action_name": "auto-tec_temp",
      "description": "获取 TEC 温度",
      "description_en": "get TEC temperature"
    },
    {
      "action_name": "auto-shg_temp_sp",
      "description": "获取/设置 SHG 温度设定值",
      "description_en": "get/set SHG temperature setpoint"
    },
    {
      "action_name": "auto-shg_temp",
      "description": "获取 SHG 温度",
      "description_en": "get SHG temperature"
    },
    {
      "action_name": "auto-shg_tune_info",
      "description": "获取 SHG 调谐就绪信息",
      "description_en": "get SHG tuning readiness information"
    },
    {
      "action_name": "auto-shg_tuning",
      "description": "执行 SHG 调谐命令",
      "description_en": "execute the SHG tuning command"
    },
    {
      "action_name": "auto-tune_shg",
      "description": "启动 SHG 调谐",
      "description_en": "start SHG tuning"
    },
    {
      "action_name": "auto-tune_shg_stop",
      "description": "停止 SHG 调谐",
      "description_en": "stop SHG tuning"
    }
  ],
  "tag_hints": [
    "laser source",
    "MPB Communications",
    "serial laser control",
    "APC/ACC control",
    "laser diode current control",
    "TEC monitoring",
    "SHG tuning"
  ]
}

